  // Set when the job ended waiting on the caller. Answer it by calling firecrawl_agent with this threadId and exchange.approve or exchange.decline carrying its id. kind "terms" lists providers whose data terms need accepting; otherwise calls lists paid calls waiting for approval.
  pendingApproval?: unknown;
  // Progress information for a running job.
  progress?: unknown;
  // Sources the agent read.
  sources?: unknown;
  // Job state: `processing` is non-terminal; `completed` and `failed` are terminal.
  status?: string | null;
  // Whether the API call succeeded.
  success?: boolean | null;
  // Follow-ups the agent offers; send one as the prompt of the next turn with this threadId.
  suggestions?: unknown;
  // Research thread this job belongs to.
  threadId?: string | null;
  // Turn number of this job within its thread.
  threadTurn?: number | null;
}>>; };
